class DqnAgent:
    tags = ["DQN"]
    """ Require use of DiscreteActionHandler in Tmenv """

    def __init__(
        self,
        model,
        exploration=EpsilonGreedyExploration(),
        device="cpu",
        gamma=0.99,
        update_target_every=320,
        optimizer_fn=partial(Adam, lr=1e-5, wd=1e-5),
        loss_fn=torch.nn.SmoothL1Loss(reduction="none"),
    ):
        store_attr()
        self.net_online = model.to(device=device)
        self.net_online.share_memory()

    @torch.no_grad()
    def select_action(self, state, evaluation=False):
        self.net_online.eval()
        action_values = self.net_online(state).squeeze().cpu()
        self.last_action_values = action_values.tolist()  # shown by the viewer
        if evaluation:
            return action_values.argmax()
        return self.exploration(action_values)

    @cached_property
    def net_target(self):
        net_target = deepcopy(self.net_online).eval()
        for p in net_target.parameters():
            p.requires_grad = False
        return net_target

    @cached_property
    def nb_batch(self):
        return 0

    @cached_property
    def optimizer(self):
        return self.optimizer_fn(self.net_online.parameters())

    @cached_property
    def scaler(self):
        return torch.amp.GradScaler(torch.device(self.device).type)

    def actor_copy(self, cpu=False):
        """Copy acting from another thread or process: its own module (train/eval flags) either sharing the
        online weights (threads) or holding a CPU copy of them (`cpu=True`, picklable for a spawned process
        where it is moved back to `device` and refreshed with `cpu_state_dict` snapshots)."""
        actor = copy(self)
        actor.__dict__ = {
            k: v for k, v in self.__dict__.items() if k not in ("net_target", "optimizer", "scaler", "nb_batch")
        }
        actor.net_online = deepcopy(self.net_online).cpu() if cpu else shared_module_copy(self.net_online)
        actor.model = actor.net_online
        return actor

    def cpu_state_dict(self):
        "Snapshot of the online network weights on the CPU, sent to collector processes."
        return {k: v.detach().to("cpu", copy=True) for k, v in self.net_online.state_dict().items()}

    def _td_estimate(self, state, action):
        return self.net_online(state)[np.arange(0, len(action)), action]

    @torch.no_grad()
    def _td_target(self, reward, next_state, done):
        next_state_Q = self.net_online(next_state)
        best_action = torch.argmax(next_state_Q, axis=1)
        next_Q = self.net_target(next_state)[
            np.arange(0, len(best_action)), best_action
        ]
        return (
            torch.tensor(reward, device=self.device)
            + (1 - torch.tensor(done, device=self.device, dtype=torch.float))
            * self.gamma
            * next_Q
        ).float()

    def _sync_Q_target(self):
        self.net_target.load_state_dict(self.net_online.state_dict())

    def set_lr(self, lr):
        self.optimizer.set_hyper("lr", lr)

    def fit_one_batch(self, batch, weights):
        state, next_state, action, reward, done = zip(*batch)

        self.net_online.train()
        with torch.autocast(torch.device(self.device).type):
            td_est = self._td_estimate(state, action)
        # Target in float32: the eval mode target net can exceed the float16 range (inf -> nan priorities)
        td_tgt = self._td_target(reward, next_state, done)
        loss = (self.loss_fn(td_est.float(), td_tgt) * weights).mean()

        self.optimizer.zero_grad()
        self.scaler.scale(loss).backward()
        self.scaler.step(self.optimizer)
        self.scaler.update()

        self.nb_batch += 1
        if self.nb_batch % self.update_target_every == 0:
            self._sync_Q_target()

        errors = torch.abs(td_est - td_tgt).detach()
        metrics = dict(
            mean_errors=errors.mean().item(),
            loss=loss.item(),
            lr=self.optimizer.param_groups[0]["lr"],
        )

        return errors, metrics

    def state_dict(self):
        return dict(
            net_online=self.net_online.state_dict(),
        )

    def load_state_dict(self, state_dict):
        self.net_online.load_state_dict(state_dict["net_online"], strict=False)
        self.net_online.to(self.device)
